#pragma once

#include "order.hpp"
#include <functional>
#include <vector>
#include <utility>

class EventManager {
public:
    // Consumer callback type to receive EngineEvent
    using EventCallback = std::function<void(const EngineEvent&)>;

    EventManager() = default;
    ~EventManager() = default;

    // Register listeners (such as Logger and Benchmark)
    void registerListener(EventCallback listener) {
        listeners_.push_back(std::move(listener));
    }

    // Publish/broadcast EngineEvent generated by the Matching Engine
    inline void publish(const EngineEvent& event) {
        for (const auto& listener : listeners_) {
            listener(event);
        }
    }

    // Disable copying to maintain single-instance data flow
    EventManager(const EventManager&) = delete;
    EventManager& operator=(const EventManager&) = delete;

private:
    std::vector<EventCallback> listeners_;
};
